=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs.v
//
// AXI4-Lite subordinate with four 32-bit read/write registers.
// Implements interface_spec.md (ports, register map, SLVERR policy, reset)
// following microarchitecture.md: holding registers instead of a skid buffer,
// READY a function of state only, one outstanding transaction per direction,
// 1-cycle response latency.

`default_nettype none

module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    // Write address channel
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    // Write data channel
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    // Write response channel
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    // Read address channel
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    // Read data channel
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State (reset)
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg                  w_held_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    reg [DATA_WIDTH-1:0] reg0_q;
    reg [DATA_WIDTH-1:0] reg1_q;
    reg [DATA_WIDTH-1:0] reg2_q;
    reg [DATA_WIDTH-1:0] reg3_q;

    // Holding registers: datapath, not reset (microarchitecture section 2).
    // They are only used while their held flag (which is reset) is set.
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [DATA_WIDTH-1:0] w_data_q;
    reg [STRB_WIDTH-1:0] w_strb_q;

    // ------------------------------------------------------------------
    // Handshakes: READY depends on state only
    // ------------------------------------------------------------------
    assign s_axil_awready = ~aw_held_q & ~bvalid_q;
    assign s_axil_wready  = ~w_held_q  & ~bvalid_q;
    assign s_axil_arready = ~rvalid_q;

    wire aw_hs = s_axil_awvalid & s_axil_awready;
    wire w_hs  = s_axil_wvalid  & s_axil_wready;
    wire ar_hs = s_axil_arvalid & s_axil_arready;
    wire b_hs  = bvalid_q & s_axil_bready;
    wire r_hs  = rvalid_q & s_axil_rready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held_q | aw_hs) & (w_held_q | w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

    // Address decode (microarchitecture section 4)
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx = wr_addr[3:2];
    wire [1:0] rd_idx = s_axil_araddr[3:2];

    // Byte mask from the strobes: bit n enables bits 8n+7:8n
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar gi;
    generate
        for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_mask
            assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register select and merge
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] wr_old;
    reg [DATA_WIDTH-1:0] wr_merged;
    reg [DATA_WIDTH-1:0] rd_sel;

    always @* begin
        case (wr_idx)
            2'd0:    wr_old = reg0_q;
            2'd1:    wr_old = reg1_q;
            2'd2:    wr_old = reg2_q;
            default: wr_old = reg3_q;
        endcase
        wr_merged = (wr_old & ~wr_mask) | (wr_data & wr_mask);
        case (rd_idx)
            2'd0:    rd_sel = reg0_q;
            2'd1:    rd_sel = reg1_q;
            2'd2:    rd_sel = reg2_q;
            default: rd_sel = reg3_q;
        endcase
    end

    // ------------------------------------------------------------------
    // Next state
    // ------------------------------------------------------------------
    reg                  aw_held_d;
    reg                  w_held_d;
    reg                  bvalid_d;
    reg [1:0]            bresp_d;
    reg                  rvalid_d;
    reg [1:0]            rresp_d;
    reg [DATA_WIDTH-1:0] rdata_d;
    reg [DATA_WIDTH-1:0] reg0_d;
    reg [DATA_WIDTH-1:0] reg1_d;
    reg [DATA_WIDTH-1:0] reg2_d;
    reg [DATA_WIDTH-1:0] reg3_d;

    always @* begin
        aw_held_d = aw_held_q;
        w_held_d  = w_held_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rresp_d   = rresp_q;
        rdata_d   = rdata_q;
        reg0_d    = reg0_q;
        reg1_d    = reg1_q;
        reg2_d    = reg2_q;
        reg3_d    = reg3_q;

        // Write side. do_write implies !bvalid_q (both READYs are low
        // while bvalid_q is high and no flag is held then), so it never
        // coincides with b_hs.
        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            bresp_d   = wr_mapped ? RESP_OKAY : RESP_SLVERR;
            if (wr_mapped) begin
                case (wr_idx)
                    2'd0:    reg0_d = wr_merged;
                    2'd1:    reg1_d = wr_merged;
                    2'd2:    reg2_d = wr_merged;
                    default: reg3_d = wr_merged;
                endcase
            end
        end else begin
            if (aw_hs) aw_held_d = 1'b1;
            if (w_hs)  w_held_d  = 1'b1;
            if (b_hs)  bvalid_d  = 1'b0;
        end

        // Read side. ar_hs implies !rvalid_q, so it never coincides with r_hs.
        if (ar_hs) begin
            rvalid_d = 1'b1;
            rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
            rdata_d  = rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
        end else if (r_hs) begin
            rvalid_d = 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // State registers (synchronous, active-low reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            w_held_q  <= 1'b0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= {DATA_WIDTH{1'b0}};
            reg0_q    <= {DATA_WIDTH{1'b0}};
            reg1_q    <= {DATA_WIDTH{1'b0}};
            reg2_q    <= {DATA_WIDTH{1'b0}};
            reg3_q    <= {DATA_WIDTH{1'b0}};
        end else begin
            aw_held_q <= aw_held_d;
            w_held_q  <= w_held_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rresp_q   <= rresp_d;
            rdata_q   <= rdata_d;
            reg0_q    <= reg0_d;
            reg1_q    <= reg1_d;
            reg2_q    <= reg2_d;
            reg3_q    <= reg3_d;
        end
    end

    // Holding registers: capture a half that is accepted without its partner.
    always @(posedge aclk) begin
        if (aw_hs && !do_write) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs && !do_write) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = bresp_q;
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = rresp_q;
    assign s_axil_rdata  = rdata_q;

    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture section 7)
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Start in reset.
    always @(*) if (!f_past_valid) assume (!aresetn);

    // Manager: VALID low during reset; VALID and payload held until READY.
    always @(*) if (!aresetn)
        assume (!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready))
                assume (s_axil_awvalid && $stable(s_axil_awaddr));
            if ($past(s_axil_wvalid && !s_axil_wready))
                assume (s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
            if ($past(s_axil_arvalid && !s_axil_arready))
                assume (s_axil_arvalid && $stable(s_axil_araddr));
        end
    end

    // Subordinate obligations.
    always @(posedge aclk) begin
        if (f_past_valid) begin
            if (!$past(aresetn)) begin
                assert (!bvalid_q && !rvalid_q && !aw_held_q && !w_held_q);
                assert (bresp_q == RESP_OKAY && rresp_q == RESP_OKAY);
            end else begin
                // Responses hold, with a stable payload, until taken.
                if ($past(bvalid_q && !s_axil_bready))
                    assert (bvalid_q && $stable(bresp_q));
                if ($past(rvalid_q && !s_axil_rready))
                    assert (rvalid_q && $stable(rresp_q) && $stable(rdata_q));
                // A response rises only one cycle after its request completes.
                if (!$past(bvalid_q) && bvalid_q)
                    assert ($past(do_write));
                if (!$past(rvalid_q) && rvalid_q)
                    assert ($past(ar_hs));
                // Every completed request gets its response, with the policy code.
                if ($past(do_write))
                    assert (bvalid_q && (bresp_q == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR)));
                if ($past(ar_hs))
                    assert (rvalid_q && (rresp_q == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR)));
            end
        end
    end

    // At most one write in flight; legal response codes only.
    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held_q && w_held_q));
            assert (!(bvalid_q && (aw_held_q || w_held_q)));
            assert (bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
            assert (rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (b_hs && bresp_q == RESP_OKAY);
            cover (b_hs && bresp_q == RESP_SLVERR);
            cover (r_hs && rresp_q == RESP_OKAY);
            cover (r_hs && rresp_q == RESP_SLVERR);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
