// axi4_lite_regs_tb.v
//
// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven after the falling edge; handshakes are evaluated just
// before the rising edge, so there is no race with the design.

`define TB_CHECK(c, m) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error m; end end

module axi4_lite_regs_tb;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  s_axil_awaddr;
    reg         s_axil_awvalid;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata;
    reg  [3:0]  s_axil_wstrb;
    reg         s_axil_wvalid;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready;
    reg  [3:0]  s_axil_araddr;
    reg         s_axil_arvalid;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready;

    integer        passed;
    integer        failed;
    integer        i;
    integer        plus_ok;
    reg            done_flag;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];

    axi4_lite_regs #(
        .ADDR_WIDTH (4),
        .DATA_WIDTH (32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    // ------------------------------------------------------------------
    // Reference model helpers
    // ------------------------------------------------------------------
    function is_mapped;
        input [3:0] a;
        begin
            is_mapped = (a[1:0] == 2'b00);
        end
    endfunction

    function [31:0] merge;
        input [31:0] old;
        input [31:0] d;
        input [3:0]  s;
        begin
            merge = { (s[3] ? d[31:24] : old[31:24]),
                      (s[2] ? d[23:16] : old[23:16]),
                      (s[1] ? d[15:8]  : old[15:8]),
                      (s[0] ? d[7:0]   : old[7:0]) };
        end
    endfunction

    task model_reset;
        begin
            model[0] = 32'h0;
            model[1] = 32'h0;
            model[2] = 32'h0;
            model[3] = 32'h0;
        end
    endtask

    // ------------------------------------------------------------------
    // Generic transaction: an optional write and an optional read, run
    // concurrently. Called and returns at a falling edge.
    //   aw_dly / w_dly / ar_dly: cycles before VALID is raised
    //   b_dly / r_dly: cycles READY is held low after VALID is seen;
    //                  negative = READY high from the start
    // ------------------------------------------------------------------
    task xact;
        input         do_wr;
        input  [3:0]  waddr;
        input  [31:0] wdata;
        input  [3:0]  wstrb;
        input integer aw_dly;
        input integer w_dly;
        input integer b_dly;
        input         do_rd;
        input  [3:0]  raddr;
        input integer ar_dly;
        input integer r_dly;
        reg           aw_done, w_done, b_done, ar_done, r_done;
        reg           aw_go, w_go, b_go, ar_go, r_go;
        reg           aw_hs, w_hs, b_hs, ar_hs, r_hs;
        reg    [1:0]  exp_bresp, exp_rresp, first_bresp, first_rresp;
        reg    [31:0] exp_rdata, first_rdata;
        integer       n, wreq, bseen, areq, rseen;
        begin
            exp_bresp   = is_mapped(waddr) ? 2'b00 : 2'b10;
            exp_rresp   = is_mapped(raddr) ? 2'b00 : 2'b10;
            exp_rdata   = is_mapped(raddr) ? model[raddr[3:2]] : 32'h0;
            first_bresp = 2'b00;
            first_rresp = 2'b00;
            first_rdata = 32'h0;
            aw_done = !do_wr;
            w_done  = !do_wr;
            b_done  = !do_wr;
            ar_done = !do_rd;
            r_done  = !do_rd;
            n     = 0;
            wreq  = -1;
            bseen = -1;
            areq  = -1;
            rseen = -1;

            while (!(b_done && r_done) && (n < 64)) begin
                // ---- observe the state left by the previous rising edge ----
                if (b_done) begin
                    `TB_CHECK(!s_axil_bvalid, ("BVALID high with no write outstanding"))
                end else if (s_axil_bvalid) begin
                    if (bseen < 0) begin
                        bseen       = n;
                        first_bresp = s_axil_bresp;
                        `TB_CHECK(aw_done && w_done, ("BVALID before both AW and W were accepted (addr %h)", waddr))
                        `TB_CHECK((n - wreq) <= 2, ("write latency %0d exceeds the bound of 2 (AXIL-LATENCY)", n - wreq))
                        `TB_CHECK((n - wreq) == 1, ("write latency %0d, the microarchitecture promises 1", n - wreq))
                        `TB_CHECK(s_axil_bresp == exp_bresp, ("BRESP %b for addr %h, expected %b", s_axil_bresp, waddr, exp_bresp))
                    end else begin
                        `TB_CHECK(s_axil_bresp == first_bresp, ("BRESP changed while B was stalled (addr %h)", waddr))
                    end
                    `TB_CHECK(!s_axil_awready && !s_axil_wready, ("AWREADY/WREADY high while a write response is pending"))
                end else begin
                    `TB_CHECK(bseen < 0, ("BVALID dropped before BREADY (addr %h)", waddr))
                    if (aw_done) `TB_CHECK(!s_axil_awready, ("AWREADY high while a write address is outstanding"))
                    if (w_done)  `TB_CHECK(!s_axil_wready, ("WREADY high while write data is outstanding"))
                    if (aw_done && w_done) `TB_CHECK((n - wreq) < 2, ("no BVALID %0d cycles after the write completed (AXIL-LATENCY)", n - wreq))
                end

                if (r_done) begin
                    `TB_CHECK(!s_axil_rvalid, ("RVALID high with no read outstanding"))
                end else if (s_axil_rvalid) begin
                    if (rseen < 0) begin
                        rseen       = n;
                        first_rresp = s_axil_rresp;
                        first_rdata = s_axil_rdata;
                        `TB_CHECK(ar_done, ("RVALID before AR was accepted (addr %h)", raddr))
                        `TB_CHECK((n - areq) <= 2, ("read latency %0d exceeds the bound of 2 (AXIL-LATENCY)", n - areq))
                        `TB_CHECK((n - areq) == 1, ("read latency %0d, the microarchitecture promises 1", n - areq))
                        `TB_CHECK(s_axil_rresp == exp_rresp, ("RRESP %b for addr %h, expected %b", s_axil_rresp, raddr, exp_rresp))
                        `TB_CHECK(s_axil_rdata == exp_rdata, ("RDATA %h for addr %h, expected %h", s_axil_rdata, raddr, exp_rdata))
                    end else begin
                        `TB_CHECK((s_axil_rdata == first_rdata) && (s_axil_rresp == first_rresp), ("RDATA/RRESP changed while R was stalled (addr %h)", raddr))
                    end
                    `TB_CHECK(!s_axil_arready, ("ARREADY high while read data is pending"))
                end else begin
                    `TB_CHECK(rseen < 0, ("RVALID dropped before RREADY (addr %h)", raddr))
                    if (ar_done) `TB_CHECK(!s_axil_arready, ("ARREADY high while a read is outstanding"))
                    if (ar_done) `TB_CHECK((n - areq) < 2, ("no RVALID %0d cycles after AR was accepted (AXIL-LATENCY)", n - areq))
                end

                // ---- drive for the next rising edge ----
                aw_go = !aw_done && (n >= aw_dly);
                w_go  = !w_done  && (n >= w_dly);
                ar_go = !ar_done && (n >= ar_dly);
                b_go  = !b_done && ((b_dly < 0) || ((bseen >= 0) && ((n - bseen) >= b_dly)));
                r_go  = !r_done && ((r_dly < 0) || ((rseen >= 0) && ((n - rseen) >= r_dly)));

                s_axil_awvalid = aw_go;
                s_axil_awaddr  = aw_go ? waddr : ~waddr;
                s_axil_wvalid  = w_go;
                s_axil_wdata   = w_go ? wdata : ~wdata;
                s_axil_wstrb   = w_go ? wstrb : ~wstrb;
                s_axil_arvalid = ar_go;
                s_axil_araddr  = ar_go ? raddr : ~raddr;
                s_axil_bready  = b_go;
                s_axil_rready  = r_go;

                #1;
                aw_hs = s_axil_awvalid && s_axil_awready;
                w_hs  = s_axil_wvalid  && s_axil_wready;
                ar_hs = s_axil_arvalid && s_axil_arready;
                b_hs  = s_axil_bvalid  && s_axil_bready;
                r_hs  = s_axil_rvalid  && s_axil_rready;

                @(posedge aclk);
                if (aw_hs) aw_done = 1'b1;
                if (w_hs)  w_done  = 1'b1;
                if (!b_done && aw_done && w_done && (wreq < 0)) wreq = n;
                if (b_hs)  b_done  = 1'b1;
                if (ar_hs) begin
                    ar_done = 1'b1;
                    areq    = n;
                end
                if (r_hs)  r_done  = 1'b1;
                @(negedge aclk);
                n = n + 1;
            end

            `TB_CHECK(b_done && r_done, ("transaction timed out: wr=%0d addr %h, rd=%0d addr %h", do_wr, waddr, do_rd, raddr))
            if (do_wr) `TB_CHECK(!s_axil_bvalid && s_axil_awready && s_axil_wready, ("write channel not ready the cycle after B was taken (AXIL-B2B)"))
            if (do_rd) `TB_CHECK(!s_axil_rvalid && s_axil_arready, ("read channel not ready the cycle after R was taken (AXIL-B2B)"))

            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_arvalid = 1'b0;
            s_axil_bready  = 1'b0;
            s_axil_rready  = 1'b0;

            if (do_wr && is_mapped(waddr))
                model[waddr[3:2]] = merge(model[waddr[3:2]], wdata, wstrb);
        end
    endtask

    task wr;
        input  [3:0]  addr;
        input  [31:0] data;
        input  [3:0]  strb;
        input integer aw_dly;
        input integer w_dly;
        input integer b_dly;
        begin
            xact(1'b1, addr, data, strb, aw_dly, w_dly, b_dly,
                 1'b0, 4'h0, 0, 0);
        end
    endtask

    task rd;
        input  [3:0]  addr;
        input integer ar_dly;
        input integer r_dly;
        begin
            xact(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0,
                 1'b1, addr, ar_dly, r_dly);
        end
    endtask

    task read_all;
        begin
            rd(4'h0, 0, 0);
            rd(4'h4, 0, 0);
            rd(4'h8, 0, 0);
            rd(4'hC, 0, 0);
        end
    endtask

    // One reset cycle, starting and ending at a falling edge.
    task pulse_reset;
        begin
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_arvalid = 1'b0;
            s_axil_bready  = 1'b0;
            s_axil_rready  = 1'b0;
            aresetn = 1'b0;
            @(posedge aclk);
            @(negedge aclk);
            aresetn = 1'b1;
            model_reset;
            `TB_CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("READY not high after reset"))
            `TB_CHECK(!s_axil_bvalid && !s_axil_rvalid, ("BVALID/RVALID not low after reset (AXIL-RESET)"))
            `TB_CHECK((s_axil_bresp == 2'b00) && (s_axil_rresp == 2'b00) && (s_axil_rdata == 32'h0), ("BRESP/RRESP/RDATA not at reset value"))
        end
    endtask

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    initial begin
        passed    = 0;
        failed    = 0;
        done_flag = 1'b0;
        nonce     = {8*64{1'b0}};
        plus_ok   = $value$plusargs("nirmaan_nonce=%s", nonce);

        aresetn        = 1'b0;
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'h0;
        s_axil_wstrb   = 4'h0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = 4'h0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        model_reset;

        // 1. Reset values
        $display("TB: reset");
        repeat (3) @(posedge aclk);
        #1;
        `TB_CHECK(!s_axil_bvalid && !s_axil_rvalid, ("BVALID/RVALID high during reset"))
        `TB_CHECK((s_axil_bresp == 2'b00) && (s_axil_rresp == 2'b00) && (s_axil_rdata == 32'h0), ("response outputs not at reset value during reset"))
        @(negedge aclk);
        aresetn = 1'b1;
        `TB_CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("READY not high after reset"))
        for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

        // 2. Write then read every register, AW and W together
        $display("TB: write/read every register");
        wr(4'h0, 32'hA5A5_0000, 4'hF, 0, 0, 0);  rd(4'h0, 0, 0);
        wr(4'h4, 32'h5A5A_1111, 4'hF, 0, 0, 0);  rd(4'h4, 0, 0);
        wr(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);  rd(4'h8, 0, 0);
        wr(4'hC, 32'hCAFE_F00D, 4'hF, 0, 0, 0);  rd(4'hC, 0, 0);
        read_all;

        // 3. AW/W ordering (AXIL-ORDER)
        $display("TB: AW/W ordering");
        wr(4'h4, 32'h1111_2222, 4'hF, 0, 3, 0);  rd(4'h4, 0, 0);   // AW first, gap 3
        wr(4'h8, 32'h3333_4444, 4'hF, 4, 0, 0);  rd(4'h8, 0, 0);   // W first, gap 4
        wr(4'hC, 32'h5555_6666, 4'hF, 2, 2, -1); rd(4'hC, 0, 0);   // together after idle, BREADY early
        wr(4'h0, 32'h7777_8888, 4'hF, 0, 1, 0);  rd(4'h0, 1, 0);   // AW one cycle ahead
        wr(4'h4, 32'h9999_AAAA, 4'hF, 1, 0, 0);  rd(4'h4, 0, -1);  // W one cycle ahead
        read_all;

        // 4. Byte strobes (AXIL-WSTRB)
        $display("TB: byte strobes");
        wr(4'h8, 32'hFFFF_FFFF, 4'hF,    0, 0, 0);
        wr(4'h8, 32'h1122_3344, 4'b0101, 0, 0, 0);  rd(4'h8, 0, 0);
        wr(4'h8, 32'h5500_0000, 4'b1000, 0, 2, 0);  rd(4'h8, 0, 0);
        wr(4'h8, 32'h0066_0000, 4'b0100, 2, 0, 0);  rd(4'h8, 0, 0);
        wr(4'h8, 32'h0000_7700, 4'b0010, 0, 0, 0);  rd(4'h8, 0, 0);
        wr(4'h8, 32'h0000_0088, 4'b0001, 0, 0, 0);  rd(4'h8, 0, 0);
        wr(4'h8, 32'hABCD_EF01, 4'b0000, 0, 0, 0);  rd(4'h8, 0, 0);  // empty strobe: unchanged, OKAY
        wr(4'hC, 32'h0123_4567, 4'b1010, 3, 0, 2);  rd(4'hC, 0, 0);
        wr(4'h0, 32'h0000_0000, 4'b0011, 0, 0, 0);  rd(4'h0, 0, 0);
        wr(4'h4, 32'hFFFF_FFFF, 4'b0000, 2, 0, 0);  rd(4'h4, 0, 0);  // empty strobe, W first
        read_all;

        // 5. Back-pressure on B and R
        $display("TB: back-pressure");
        wr(4'hC, 32'h0BAD_CAFE, 4'hF, 0, 0, 5);  rd(4'hC, 0, 6);
        wr(4'h0, 32'h1357_9BDF, 4'hF, 3, 0, 4);  rd(4'h0, 2, 3);
        rd(4'h4, 0, 8);

        // 6. Back-to-back transactions (AXIL-B2B)
        $display("TB: back-to-back");
        for (i = 0; i < 8; i = i + 1) wr({i[1:0], 2'b00}, 32'hC0DE_0000 + i, 4'hF, 0, 0, 0);
        for (i = 0; i < 8; i = i + 1) rd({i[1:0], 2'b00}, 0, -1);
        for (i = 0; i < 4; i = i + 1) wr({i[1:0], 2'b00}, 32'h0F0F_0000 + i, 4'hF, 0, 0, -1);
        for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

        // 7. Unmapped addresses (AXIL-SLVERR)
        $display("TB: SLVERR policy");
        wr(4'h5, 32'hBAD0_0001, 4'hF, 0, 0, 0);
        wr(4'hE, 32'hBAD0_0002, 4'hF, 3, 0, 2);
        wr(4'h2, 32'hBAD0_0003, 4'h1, 0, 2, 0);
        wr(4'h7, 32'hBAD0_0004, 4'hF, 0, 0, 3);
        wr(4'h1, 32'hBAD0_0005, 4'h0, 0, 0, 0);
        read_all;   // no register changed
        rd(4'hE, 0, 0);
        rd(4'h1, 0, 3);
        rd(4'h3, 1, 0);
        rd(4'hD, 0, -1);
        rd(4'h6, 0, 0);

        // 8. Concurrent read and write
        $display("TB: concurrent read and write");
        xact(1'b1, 4'h4, 32'h2468_ACE0, 4'hF,    0, 0, 0, 1'b1, 4'h8, 0, 0);  // AW, W, AR on one edge
        xact(1'b1, 4'h0, 32'h1122_3344, 4'hF,    2, 0, 3, 1'b1, 4'hC, 0, 2);
        xact(1'b1, 4'hC, 32'h5566_7788, 4'b0110, 0, 1, 0, 1'b1, 4'h9, 1, 0);  // unmapped read
        xact(1'b1, 4'h6, 32'hBAD0_0006, 4'hF,    0, 0, 2, 1'b1, 4'h0, 0, 0);  // unmapped write
        read_all;

        // 9a. Reset with a half-accepted AW (AXIL-RESET)
        $display("TB: reset during traffic");
        wr(4'h4, 32'hFACE_0004, 4'hF, 0, 0, 0);
        s_axil_awaddr  = 4'h4;
        s_axil_awvalid = 1'b1;
        #1;
        `TB_CHECK(s_axil_awready, ("AWREADY low before the half write"))
        @(posedge aclk);
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_awaddr  = 4'h0;
        `TB_CHECK(!s_axil_awready && s_axil_wready && !s_axil_bvalid, ("AW not held while waiting for W"))
        pulse_reset;
        wr(4'h8, 32'h0000_8888, 4'hF, 3, 0, 0);   // W first: a stale AW would pair at once
        rd(4'h4, 0, 0);
        rd(4'h8, 0, 0);

        // 9b. Reset with a half-accepted W
        s_axil_wdata  = 32'h7777_7777;
        s_axil_wstrb  = 4'hF;
        s_axil_wvalid = 1'b1;
        #1;
        `TB_CHECK(s_axil_wready, ("WREADY low before the half write"))
        @(posedge aclk);
        @(negedge aclk);
        s_axil_wvalid = 1'b0;
        s_axil_wdata  = 32'h0;
        s_axil_wstrb  = 4'h0;
        `TB_CHECK(!s_axil_wready && s_axil_awready && !s_axil_bvalid, ("W not held while waiting for AW"))
        pulse_reset;
        wr(4'hC, 32'h1234_5678, 4'h3, 0, 3, 0);   // AW first: a stale W would pair at once
        rd(4'hC, 0, 0);

        // 9c. Reset with B and R pending
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b1;
        s_axil_wdata   = 32'hFFFF_0000;
        s_axil_wstrb   = 4'hF;
        s_axil_wvalid  = 1'b1;
        s_axil_araddr  = 4'hC;
        s_axil_arvalid = 1'b1;
        s_axil_bready  = 1'b0;
        s_axil_rready  = 1'b0;
        #1;
        `TB_CHECK(s_axil_awready && s_axil_wready && s_axil_arready, ("not ready before pending-response reset test"))
        @(posedge aclk);
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        `TB_CHECK(s_axil_bvalid && s_axil_rvalid, ("B and R not pending"))
        @(posedge aclk);
        @(negedge aclk);
        `TB_CHECK(s_axil_bvalid && s_axil_rvalid, ("B or R dropped while stalled"))
        pulse_reset;
        read_all;

        // Final consistency check
        $display("TB: final read-back");
        wr(4'h0, 32'h0000_0001, 4'hF, 0, 0, 0);
        wr(4'h4, 32'h0000_0002, 4'hF, 1, 0, 0);
        wr(4'h8, 32'h0000_0003, 4'hF, 0, 1, 0);
        wr(4'hC, 32'h0000_0004, 4'hF, 0, 0, 1);
        read_all;

        done_flag = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung handshake ends the run as a failure.
    initial begin
        #200000;
        if (!done_flag) begin
            failed = failed + 1;
            $error("watchdog: simulation did not complete");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end

endmodule
